async function setup(){const {db,DB}=openDatabase(':memory:'),origin='https://card-native.test';for(const user of ['alice','bob']){db.prepare('INSERT INTO auth_users VALUES(?,?,?,?)').run(user,user,user+'@example.test',Date.now());db.prepare('INSERT INTO auth_sessions VALUES(?,?,?)').run(createHash('sha256').update(user).digest('hex'),user,Date.now()+1000000)}const app=createApp({db,DB,origin,allowedEmails:['alice@example.test','bob@example.test'],reportOptions:{key:randomBytes(32),recoveryPublicKey:pair.publicKey}}),req=(user,path,opt={})=>app(new Request(origin+path,{...opt,headers:{origin,cookie:'__Host-mf_session='+user,'Content-Type':'application/json',...opt.headers}})),fetcher=user=>(path,opt)=>req(user,path,opt);for(const user of ['alice','bob'])await req(user,'/api/plan',{method:'PUT',body:JSON.stringify({plan:base(),revision:0})});const a=fetcher('alice'),snapshot=(await loadBudgetSnapshot('personal',signal(),a)).value,receipt=await storeReportSource('personal',snapshot,'source.xlsx',sourceBytes,a),stored=await loadStoredReport('personal',snapshot,receipt.receiptId,signal(),a);return{db,req,fetcher,snapshot,stored}}
test('Native card review equals the original statement/batch/receipt model and preserves source cycle, original installment price and input',async()=>{const p=base(),before=clone(p),r=parsed(),s=source(),selected=selection(),result=await prepareNativeCardReport(p,r,s,selected,'2026-10-27'),preview=await prepareCardStatement(p,r.report,'card1'),expected=await applyReportInbox(p,[],[{cardId:'card1',accountId:'a',dueDate:r.report.dueDate,amount:r.report.amount,statement:preview,choices:{[preview.rows[0].id]:{category:'מזון'}},deferCategories:false}],[{hash:sourceHash,kind:'card',target:'card1',reference:r.report.dueDate}],[{key:r.identityKey,kind:'card',target:'card1'}],'2026-10-27');assert.deepEqual(result.plan,expected);assert.equal(result.plan.details[0].amount,100.01);assert.equal(result.plan.details[0].statement.originalCents,20002);assert.equal(result.plan.details[0].month,'2026-11');assert.deepEqual(result.plan.months,p.months);assert.deepEqual(p,before);assert.ok(validatePlan(result.plan))})
test('Optional merchant categories preserve the original workflow while payer/card/source and grouped-draft guards remain enforced',async()=>{const p=base(),r=parsed(),s=source();const deferred=await prepareNativeCardReport(p,r,s,{...selection(),categories:{}},'2026-10-27'),statement=await prepareCardStatement(p,r.report,'card1'),original=await applyReportInbox(p,[],[{cardId:'card1',accountId:'a',dueDate:r.report.dueDate,amount:r.report.amount,statement,choices:{},deferCategories:true}],[{hash:sourceHash,kind:'card',target:'card1',reference:r.report.dueDate}],[{key:r.identityKey,kind:'card',target:'card1'}],'2026-10-27');assert.deepEqual(deferred.plan,original);assert.equal(deferred.plan.details[0].category,'לסיווג');await assert.rejects(prepareNativeCardReport(p,r,s,{...selection(),categories:{'חנות בדיקה':'invalid category'}},'2026-10-27'),/קטגוריה/);await assert.rejects(previewNativeCardReport(p,r,s,{...selection(),payerId:'foreign'}));const wrong=base();wrong.creditCards[0].alias='9999';await assert.rejects(previewNativeCardReport(wrong,r,s,selection()),/תואמות/);await assert.rejects(previewNativeCardReport(p,r,{...s,draft:{version:1,items:[{},{}]}},selection()),/קבוצת/);await assert.rejects(previewNativeCardReport(p,{...r,hash:'bad'},s,selection()))})
test('Saving review progress uses existing group schema/revisions and a completed card import atomically commits plan, receipt and source state',async()=>{const c=await setup();try{const a=c.fetcher('alice'),s=c.stored,r=parsed(),d=nativeCardStoredDraft(c.snapshot.plan,r,s,selection(),id),prepared=await prepareNativeCardReport(c.snapshot.plan,r,s,selection(),'2026-10-27');const saved=await commitStoredCardReport('personal',c.snapshot,s,d,prepared.plan,id,a);assert.equal(saved.value.revision,2);assert.equal(saved.recovered,false);const stored=await loadStoredReport('personal',saved.value,s.id,signal(),a);assert.equal(stored.state,'committed');assert.equal(stored.revision,3);assert.equal(stored.draft.version,1);assert.equal(stored.draft.items[0].storedRevision,2);assert.equal(c.db.prepare('SELECT revision FROM plans WHERE user_id=?').get('bob').revision,1);assert.equal(c.db.prepare("SELECT kind FROM plan_history WHERE scope='personal:alice' ORDER BY revision DESC LIMIT 1").get()?.kind,'report-import')}finally{c.db.close()}})
test('Lost atomic-commit receipt is acknowledged without duplicate statements, details or another commit',async()=>{const c=await setup();try{const a=c.fetcher('alice'),s=c.stored,d=nativeCardStoredDraft(c.snapshot.plan,parsed(),s,selection(),id),prepared=await prepareNativeCardReport(c.snapshot.plan,parsed(),s,selection(),'2026-10-27');let commits=0;const lost=async(path,opt={})=>{if(opt.method==='POST'&&JSON.parse(opt.body).action==='commit'){commits++;await a(path,opt);return Response.json({error:'lost'},{status:503})}return a(path,opt)};await assert.rejects(commitStoredCardReport('personal',c.snapshot,s,d,prepared.plan,id,lost));const result=await commitStoredCardReport('personal',c.snapshot,s,d,prepared.plan,id,lost);assert.equal(result.recovered,true);assert.equal(commits,1);assert.equal(result.value.plan.details.length,1);assert.equal(result.value.plan.cardBilling.reports.length,1);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM report_commits').get().n,1)}finally{c.db.close()}})
test('Source revision conflicts, concurrent financial saves and session switches prevent an import without applying a partial budget',async()=>{const c=await setup();try{const a=c.fetcher('alice'),s=c.stored,d=nativeCardStoredDraft(c.snapshot.plan,parsed(),s,selection(),id),prepared=await prepareNativeCardReport(c.snapshot.plan,parsed(),s,selection(),'2026-10-27');await saveStoredReportDraft('personal',c.snapshot,s,d,'needs_review',a);const changed=clone(d);changed.categoryChoices=[];await assert.rejects(saveStoredReportDraft('personal',c.snapshot,s,changed,'ready',a),/השתנה/);await c.req('alice','/api/plan',{method:'PUT',body:JSON.stringify({plan:{...c.snapshot.plan,buffer:500},revision:1})});await assert.rejects(commitStoredCardReport('personal',c.snapshot,s,d,prepared.plan,id,a),/השתנו/);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM report_commits').get().n,0);const switched=async(path,opt={})=>opt.method==='POST'?c.req('bob',path,opt):a(path,opt);await assert.rejects(saveStoredReportDraft('personal',c.snapshot,{...s,revision:2},{...d,items:[{...d.items[0],storedRevision:3}]},'ready',switched),AccessError);assert.equal(c.db.prepare('SELECT revision FROM plans WHERE user_id=?').get('bob').revision,1)}finally{c.db.close()}})

