test('Report archiving/reactivation preserves source bytes, review choices and all financial revisions',async()=>{const c=await setup();try{const a=c.fetcher('alice'),s=c.stored,d=nativeCardStoredDraft(c.snapshot.plan,parsed(),s,selection(),id),draft=await saveStoredReportDraft('personal',c.snapshot,s,d,'ready',a),archived=await changeStoredReportState('personal',c.snapshot,draft,'archive','לבדיקה מאוחרת',a);assert.equal(archived.source.state,'archived');assert.deepEqual(archived.source.draft,d);const active=await changeStoredReportState('personal',c.snapshot,archived.source,'reactivate','',a);assert.equal(active.source.state,'needs_review');assert.deepEqual(active.source.draft.categoryChoices,d.categoryChoices);assert.equal(active.source.draft.items[0].storedRevision,active.source.revision);const bytes=await c.req('alice','/api/reports?budget=personal&id='+s.id+'&source=1');assert.deepEqual(new Uint8Array(await bytes.arrayBuffer()),sourceBytes);assert.equal(c.db.prepare('SELECT revision FROM plans WHERE user_id=?').get('alice').revision,1);assert.equal(c.db.prepare('SELECT revision FROM plans WHERE user_id=?').get('bob').revision,1)}finally{c.db.close()}})
test('Lost archive and reactivation acknowledgments recover the verified next revision without replay',async()=>{const c=await setup();try{const a=c.fetcher('alice'),s=c.stored;let writes=0;const lost=async(path,opt={})=>{if(opt.method==='POST'){writes++;await a(path,opt);throw Error('offline')}return a(path,opt)};await assert.rejects(changeStoredReportState('personal',c.snapshot,s,'archive','כפילות לבדיקה',lost),/לא ניתן לאשר/);const archived=await changeStoredReportState('personal',c.snapshot,s,'archive','כפילות לבדיקה',lost);assert.equal(archived.recovered,true);assert.equal(writes,1);await assert.rejects(changeStoredReportState('personal',c.snapshot,archived.source,'reactivate','',lost));const active=await changeStoredReportState('personal',c.snapshot,archived.source,'reactivate','',lost);assert.equal(active.recovered,true);assert.equal(active.source.state,'received');assert.equal(writes,2)}finally{c.db.close()}})
test('Archive reason, stale revisions, committed sources and changed mutation actors are refused',async()=>{const c=await setup();try{const a=c.fetcher('alice'),s=c.stored;await assert.rejects(changeStoredReportState('personal',c.snapshot,s,'archive',' ',a));const changed=await changeStoredReportState('personal',c.snapshot,s,'archive','סיבה ראשונה',a);await assert.rejects(changeStoredReportState('personal',c.snapshot,s,'archive','סיבה שונה',a),/השתנה/);const active=await changeStoredReportState('personal',c.snapshot,changed.source,'reactivate','',a);const switched=(path,opt={})=>opt.method==='POST'?c.req('bob',path,opt):a(path,opt);await assert.rejects(changeStoredReportState('personal',c.snapshot,active.source,'archive','סיבה',switched),AccessError);const d=nativeCardStoredDraft(c.snapshot.plan,parsed(),active.source,selection(),id),prepared=await prepareNativeCardReport(c.snapshot.plan,parsed(),active.source,selection(),'2026-10-27'),saved=await commitStoredCardReport('personal',c.snapshot,active.source,d,prepared.plan,id,a),committed=await loadStoredReport('personal',saved.value,s.id,signal(),a);await assert.rejects(changeStoredReportState('personal',saved.value,committed,'archive','לא מתאים',a),/אינה זמינה/)}finally{c.db.close()}})

