test('Bank review progress saves bank metadata without financial changes and atomically commits once after a lost response',async()=>{const c=await setup();try{const a=c.fetcher('alice'),s=c.stored,r={kind:'bank',hash:s.sourceHash,identityKey:'d'.repeat(64),from:'2026-02-01',to:'2026-02-28',records:[{line:2,date:'2026-02-28',reference:'salary-1',amountCents:10001,description:'משכורת',valid:true,currency:'ILS',balanceCents:110001,details:'',beneficiary:'',purpose:''}]},selected={accountId:'a',scope:'complete',choices:{},duplicates:{},skipMonths:[],directIncluded:{}},d=await nativeBankStoredDraft(c.snapshot.plan,r,s,selected,id,'2026-10'),progress=await saveStoredReportDraft('personal',c.snapshot,s,d,'ready',a);assert.equal(c.db.prepare('SELECT kind FROM report_sources WHERE id=?').get(s.id).kind,'bank');assert.equal(c.db.prepare('SELECT revision FROM plans WHERE user_id=?').get('alice').revision,1);const stored=await loadStoredReport('personal',c.snapshot,s.id,signal(),a),restored=await restoreNativeBankSelection(c.snapshot.plan,r,stored,'2026-10');assert.deepEqual(restored,selected);const resumed={...stored,draft:null},prepared=await prepareNativeBankReport(c.snapshot.plan,r,resumed,restored,'2026-10'),nextDraft=await nativeBankStoredDraft(c.snapshot.plan,r,resumed,restored,id,'2026-10');let commits=0;const lost=async(path,opt={})=>{if(opt.method==='POST'&&JSON.parse(opt.body).action==='commit'){commits++;await a(path,opt);throw Error('offline')}return a(path,opt)};await assert.rejects(commitStoredCardReport('personal',c.snapshot,progress,nextDraft,prepared.plan,id,lost));const saved=await commitStoredCardReport('personal',c.snapshot,progress,nextDraft,prepared.plan,id,lost);assert.equal(saved.recovered,true);assert.equal(commits,1);assert.equal(saved.value.plan.bankImport.batches.length,1);assert.equal(c.db.prepare('SELECT revision FROM plans WHERE user_id=?').get('bob').revision,1)}finally{c.db.close()}})
test('Report progress cannot mislabel a bank source or save a different source receipt',async()=>{const c=await setup();try{const d=nativeCardStoredDraft(c.snapshot.plan,parsed(),c.stored,selection(),id);await assert.rejects(saveStoredReportDraft('personal',c.snapshot,c.stored,{...d,items:[{...d.items[0],hash:'f'.repeat(64)}]},'ready',c.fetcher('alice')),/אינה תואמת/);assert.equal(c.db.prepare('SELECT revision FROM report_sources WHERE id=?').get(c.stored.id).revision,1)}finally{c.db.close()}})

test('Lost bank-progress receipt retries the identical draft without advancing source revision twice or touching finances',async()=>{const c=await setup();try{const a=c.fetcher('alice'),s=c.stored,r={kind:'bank',hash:s.sourceHash,identityKey:'e'.repeat(64),from:'2026-02-01',to:'2026-02-28',records:[{line:2,date:'2026-02-28',reference:'salary',amountCents:10001,description:'משכורת',valid:true,currency:'ILS',balanceCents:null,details:'',beneficiary:'',purpose:''}]},selected={accountId:'a',scope:'complete',choices:{},duplicates:{},skipMonths:[],directIncluded:{}},d=await nativeBankStoredDraft(c.snapshot.plan,r,s,selected,id,'2026-10');let first=true,writes=0;const lost=async(path,opt={})=>{if(opt.method==='POST'){writes++;const response=await a(path,opt);if(first){first=false;throw Error('offline')}return response}return a(path,opt)};await assert.rejects(saveStoredReportDraft('personal',c.snapshot,s,d,'ready',lost),/לא ניתן לאשר/);const saved=await saveStoredReportDraft('personal',c.snapshot,s,d,'ready',lost);assert.equal(saved.revision,2);assert.equal(writes,2);const row=c.db.prepare('SELECT revision,kind,month,target FROM report_sources WHERE id=?').get(s.id);assert.equal(row.revision,2);assert.equal(row.kind,'bank');assert.equal(row.month,'2026-02');assert.equal(row.target,'a');assert.equal(c.db.prepare('SELECT revision FROM plans WHERE user_id=?').get('alice').revision,1);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM report_commits').get().n,0)}finally{c.db.close()}})

async function sharedBankFixture(role='viewer'){const c=await setup(),a=c.fetcher('alice'),house=(await(await c.req('alice','/api/budgets',{method:'POST',body:JSON.stringify({name:'בית לבדיקה'})})).json()).id;await c.req('alice','/api/plan?budget='+house,{method:'PUT',body:JSON.stringify({plan:base(),revision:0})});const invitation=await(await c.req('alice','/api/budgets/'+house+'/invites',{method:'POST',body:JSON.stringify({email:'bob@example.test',role})})).json();await c.req('bob','/api/budgets/accept',{method:'POST',body:JSON.stringify({token:invitation.token})});const snapshot=(await loadBudgetSnapshot(house,signal(),a)).value,receipt=await storeReportSource(house,snapshot,'bank.csv',sourceBytes,a),stored=await loadStoredReport(house,snapshot,receipt.receiptId,signal(),a),r={kind:'bank',hash:stored.sourceHash,identityKey:'d'.repeat(64),from:'2026-02-01',to:'2026-02-28',records:[{line:2,date:'2026-02-28',reference:'salary',amountCents:10001,description:'משכורת',valid:true,currency:'ILS',balanceCents:110001,details:'',beneficiary:'',purpose:''}]},selected={accountId:'a',scope:'complete',choices:{},duplicates:{},skipMonths:[],directIncluded:{}},draft=await nativeBankStoredDraft(snapshot.plan,r,stored,selected,id,'2026-10'),prepared=await prepareNativeBankReport(snapshot.plan,r,stored,selected,'2026-10');return{...c,house,snapshot,stored,r,selected,draft,prepared}}
test('Shared bank source is readable by viewers but draft and final import writes are refused without touching any financial scope',async()=>{const c=await sharedBankFixture();try{const b=c.fetcher('bob'),snapshot=(await loadBudgetSnapshot(c.house,signal(),b)).value,source=await loadStoredReport(c.house,snapshot,c.stored.id,signal(),b);assert.equal(source.sourceHash,c.stored.sourceHash);await assert.rejects(saveStoredReportDraft(c.house,snapshot,source,c.draft,'ready',b),/לצפייה/);await assert.rejects(commitStoredCardReport(c.house,snapshot,source,c.draft,c.prepared.plan,id,b),/לצפייה/);assert.equal(c.db.prepare('SELECT revision FROM budgets WHERE id=?').get(c.house).revision,1);assert.equal(c.db.prepare('SELECT revision FROM report_sources WHERE id=?').get(source.id).revision,1);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM report_commits').get().n,0);assert.equal(c.db.prepare('SELECT revision FROM plans WHERE user_id=?').get('alice').revision,1);assert.equal(c.db.prepare('SELECT revision FROM plans WHERE user_id=?').get('bob').revision,1)}finally{c.db.close()}})
test('Shared bank editor downgrade immediately before draft mutation prevents both source progress and financial import',async()=>{const c=await sharedBankFixture('editor');try{const b=c.fetcher('bob'),snapshot=(await loadBudgetSnapshot(c.house,signal(),b)).value;let downgraded=false;const race=async(path,opt={})=>{if(opt.method==='POST'&&!downgraded){downgraded=true;await c.req('alice','/api/budgets/'+c.house+'/members/bob',{method:'PATCH',body:JSON.stringify({role:'viewer',expectedRole:'editor'})})}return b(path,opt)};await assert.rejects(commitStoredCardReport(c.house,snapshot,c.stored,c.draft,c.prepared.plan,id,race),AccessError);assert.equal(downgraded,true);assert.equal(c.db.prepare('SELECT revision FROM report_sources WHERE id=?').get(c.stored.id).revision,1);assert.equal(c.db.prepare('SELECT revision FROM budgets WHERE id=?').get(c.house).revision,1);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM report_commits').get().n,0)}finally{c.db.close()}})
test('Concurrent shared financial save at final bank commit preserves the newer budget and leaves source ready without a partial import',async()=>{const c=await sharedBankFixture('editor');try{const a=c.fetcher('alice');let changed=false;const race=async(path,opt={})=>{if(opt.method==='POST'&&JSON.parse(opt.body).action==='commit'){changed=true;const response=await c.req('alice','/api/plan?budget='+c.house,{method:'PUT',body:JSON.stringify({revision:1,plan:{...c.snapshot.plan,buffer:777}})});assert.equal(response.status,200)}return a(path,opt)};await assert.rejects(commitStoredCardReport(c.house,c.snapshot,c.stored,c.draft,c.prepared.plan,id,race));assert.equal(changed,true);const saved=(await loadBudgetSnapshot(c.house,signal(),a)).value;assert.equal(saved.revision,2);assert.equal(saved.plan.buffer,777);assert.equal(saved.plan.bankImport,undefined);const source=await loadStoredReport(c.house,saved,c.stored.id,signal(),a);assert.equal(source.state,'ready');assert.equal(source.revision,2);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM report_commits').get().n,0);const restored=await restoreNativeBankSelection(saved.plan,c.r,source,'2026-10'),resumed={...source,draft:null},next=await prepareNativeBankReport(saved.plan,c.r,resumed,restored,'2026-10'),draft=await nativeBankStoredDraft(saved.plan,c.r,resumed,restored,id,'2026-10'),completed=await commitStoredCardReport(c.house,saved,source,draft,next.plan,'bank-resume-reviewed-2026',a);assert.equal(completed.value.revision,3);assert.equal(completed.value.plan.buffer,777);assert.equal(completed.value.plan.bankImport.batches.length,1);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM report_commits').get().n,1)}finally{c.db.close()}})

function nativeActivity(){const fixture=activityFixture();fixture.rows[0].cells[0]=fixture.rows[0].cells[0].replace('1111','1234');return{...parseCalActivity([fixture]),hash:sourceHash,identityKey:'e'.repeat(64)}}
