test('Native activity requires original-source cycle, matching final total and acknowledgment; monthly details and derived receipt preserve original semantics',async()=>{const raw=nativeActivity(),before=clone(raw);for(const [cycle,total,ack]of [['','90',true],['2026-10-15','430',true],['2026-10-15','90',false],['2026-12-15','90',true]])assert.throws(()=>selectNativeActivity(raw,cycle,total,ack));const selected=selectNativeActivity(raw,'2026-10-15','90',true),prepared=await prepareNativeCardReport(base(),selected,source(),activitySelection(),'2026-10-28');assert.equal(prepared.plan.cardBilling.reports[0].amount,90);assert.equal(prepared.plan.details.length,2);assert.deepEqual(prepared.plan.details.map(r=>r.amount),[100,-10]);const receipt=prepared.plan.reportInbox.receipts[0];assert.equal(receipt.hash,createHash('sha256').update(sourceHash+':cal-cycle:2026-10-15').digest('hex'));assert.notEqual(receipt.hash,sourceHash);assert.deepEqual(raw,before);const changed={...selected,report:{...selected.report,amount:430}};await assert.rejects(prepareNativeCardReport(base(),changed,source(),activitySelection(),'2026-10-28'));const installment=clone(raw);installment.activity.entries[4].dueDate='2026-10-15';assert.throws(()=>selectNativeActivity(installment,'2026-10-15','390',true),/תשלום חודשי/)})
test('Stored native activity choices resume exactly and atomically commit a validated cycle receipt with no duplicate import after a lost response',async()=>{const c=await setup();try{const a=c.fetcher('alice'),raw=nativeActivity(),selected=selectNativeActivity(raw,'2026-10-15','90',true),d=nativeCardStoredDraft(c.snapshot.plan,selected,c.stored,activitySelection(),id),progress=await saveStoredReportDraft('personal',c.snapshot,c.stored,d,'ready',a),restored=restoreNativeActivity(raw,progress),prepared=await prepareNativeCardReport(c.snapshot.plan,restored,progress,activitySelection(),'2026-10-28'),nextDraft=nativeCardStoredDraft(c.snapshot.plan,restored,progress,activitySelection(),id);assert.deepEqual(restored,selected);assert.equal(activityReceiptPresent(prepared.plan,nextDraft,c.stored.id,c.stored.sourceHash),true);let commits=0;const lost=async(path,opt={})=>{if(opt.method==='POST'&&JSON.parse(opt.body).action==='commit'){commits++;await a(path,opt);throw Error('offline')}return a(path,opt)};await assert.rejects(commitStoredCardReport('personal',c.snapshot,progress,nextDraft,prepared.plan,id,lost));const saved=await commitStoredCardReport('personal',c.snapshot,progress,nextDraft,prepared.plan,id,lost);assert.equal(saved.recovered,true);assert.equal(commits,1);assert.equal(saved.value.plan.details.length,2);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM report_commits').get().n,1);assert.equal(c.db.prepare('SELECT revision FROM plans WHERE user_id=?').get('bob').revision,1)}finally{c.db.close()}})
test('Activity commit refuses missing acknowledgment, changed report, wrong cycle receipt or proof and rolls financial writes back atomically',async()=>{const c=await setup();try{const a=c.fetcher('alice'),selected=selectNativeActivity(nativeActivity(),'2026-10-15','90',true),d=nativeCardStoredDraft(c.snapshot.plan,selected,c.stored,activitySelection(),id),prepared=await prepareNativeCardReport(c.snapshot.plan,selected,c.stored,activitySelection(),'2026-10-28');for(const edit of [draft=>{draft.items[0].activityConfirmed=false},draft=>{draft.items[0].activityTotal='430'},draft=>{draft.items[0].report.amount=430},draft=>{draft.items[0].activityCycle='2026-11-15'}]){const changed=clone(d);edit(changed);assert.equal(activityReceiptPresent(prepared.plan,changed,c.stored.id,c.stored.sourceHash),false)}for(const edit of [plan=>{plan.reportInbox.receipts[0].proof='f'.repeat(64)},plan=>{plan.reportInbox.receipts[0].hash='f'.repeat(64)},plan=>{plan.reportInbox.receipts[0].target='other'}]){const changed=clone(prepared.plan);edit(changed);assert.equal(activityReceiptPresent(changed,d,c.stored.id,c.stored.sourceHash),false)}const invalid=clone(d);invalid.items[0].activityConfirmed=false;await assert.rejects(commitStoredCardReport('personal',c.snapshot,c.stored,invalid,prepared.plan,id,a));assert.equal(c.db.prepare('SELECT revision FROM plans WHERE user_id=?').get('alice').revision,1);assert.equal(c.db.prepare('SELECT COUNT(*) n FROM report_commits').get().n,0);assert.equal(c.db.prepare('SELECT state FROM report_sources WHERE id=?').get(c.stored.id).state,'ready')}finally{c.db.close()}})

