test('Explicit manual correction of a bank month matches the original form record, retains source evidence and other accounts, and clears only the combined anchor',async()=>{const c=await mixedOriginalGroup();try{const {ui}=c.group,p=clone(ui.build),month='2026-02';p.cashPlanning.accounts.push({id:'b',label:'נשאר',buffer:0,opening:200,openingMonth:'2026-01'});const sourceRecord=cashAccountValues(p,'a',month).record;p.cashPlanning.months[month]??={};p.cashPlanning.months[month].a={values:clone(cashAccountValues(p,'a',month).values),actual:sourceRecord.actual,includesPlannedCard:sourceRecord.includesPlannedCard,includesPlannedDirect:sourceRecord.includesPlannedDirect,balance:sourceRecord.balance,date:sourceRecord.date,bankImported:true};p.cashPlanning.months[month].b={values:{...zero(),salary:50},actual:true,includesPlannedCard:false,includesPlannedDirect:false};p.months[month].values.salary+=50;p.months[month].cashReport={balance:1300.01,net:100.01};assert.equal(validatePlan(p),true);const before=clone(p),other=cashAccountForecast(p,'b'),draft=initialCashMonthlyDraft(p,'a',month);draft.values.salary='200.02';draft.balance='-12.34';draft.actual=true;assert.ok(cashMonthlyEligibility(p,'a',month));assert.equal(cashMonthlyEligibility(p,'a',month,{sourceAware:true}),null);const result=prepareCashMonthlyReport(p,'a',month,draft,'2026-10',{sourceAware:true}),record={values:{...before.cashPlanning.months[month].a.values,salary:200.02},actual:true,includesPlannedCard:draft.includesCard,includesPlannedDirect:draft.includesDirect,balance:-12.34};assert.deepEqual(result,saveCashMonth(p,'a',month,record,'2026-10'));assert.equal(result.cashPlanning.months[month].a.bankImported,undefined);assert.equal(result.cashPlanning.months[month].a.date,undefined);assert.equal(result.months[month].cashReport,undefined);assert.equal(result.months[month].values.salary,250.02);assert.deepEqual(result.bankImport,before.bankImport);assert.deepEqual(result.reportInbox,before.reportInbox);assert.deepEqual(result.cardBilling,before.cardBilling);assert.deepEqual(result.details,before.details);assert.deepEqual(result.cashPlanning.months[month].b,before.cashPlanning.months[month].b);assert.deepEqual(cashAccountForecast(result,'b'),other);assert.deepEqual(p,before);assert.throws(()=>undoBankImport(result,p.bankImport.batches[0].id),/הנתונים השתנו/)}finally{c.db.close()}})
test('Source-backed metadata and manual correction save through the existing actor/revision boundary and recover without changing the original file',async()=>{const c=await mixedOriginalGroup();try{const {ui,sources}=c.group,imported=await commitStoredReportGroup('personal',c.snapshot,sources,reportInboxDraftForWrite(ui,ui.items,'react-group-review-v1'),ui.build,id,c.a),bank=sources.find(source=>source.name==='bank.csv'),bytesBefore=c.db.prepare('SELECT source,draft,state,revision FROM report_sources WHERE id=?').get(bank.id),metadata=prepareManualAccount(imported.value.plan,'a',{...initialAccountDraft(imported.value.plan,'a','2026-10'),label:'שם מעודכן',color:'blue'},{asOf:'2026-10'}),renamed=await savePreparedPlan({budgetId:'personal',base:imported.value,plan:metadata},c.a),draft=initialCashMonthlyDraft(renamed.value.plan,'a','2026-02');draft.values.salary='333.33';const plan=prepareCashMonthlyReport(renamed.value.plan,'a','2026-02',draft,'2026-10',{sourceAware:true});let writes=0;const lost=async(path,opt={})=>{if(opt.method==='PUT'){writes++;await c.a(path,opt);throw Error('lost correction')}return c.a(path,opt)},input={budgetId:'personal',base:renamed.value,plan};await assert.rejects(savePreparedPlan(input,lost),SaveUncertain);const saved=await savePreparedPlan(input,lost);assert.equal(saved.recovered,true);assert.equal(writes,1);assert.equal(saved.value.plan.cashPlanning.months['2026-02'].a.values.salary,333.33);assert.equal(saved.value.plan.cashPlanning.accounts.find(a=>a.id==='a').label,'שם מעודכן');assert.deepEqual(saved.value.plan.bankImport,imported.value.plan.bankImport);assert.deepEqual(c.db.prepare('SELECT source,draft,state,revision FROM report_sources WHERE id=?').get(bank.id),bytesBefore);assert.equal(c.db.prepare('SELECT revision FROM plans WHERE user_id=?').get('bob').revision,1)}finally{c.db.close()}})

