test('Deferred merchant categorization and exact-cent splits reuse original annotation rules without changing the statement, source or cash flow',async()=>{const c=await deferredAnnotationFixture();try{const p=c.saved.value.plan,before=clone(p),draft=initialAnnotationDraft(p,c.detailId,annotationOptions);assert.equal(draft.parts[0].category,'לסיווג');draft.parts=[{category:'מזון',amount:'60.01',person:'משותף',event:''},{category:'משפחה',amount:'40',person:'אישי',event:'אירוע'}];const next=prepareDetailAnnotation(p,c.detailId,draft,annotationOptions),expected=annotateExpenseDetail(p,c.detailId,[{category:'מזון',cents:6001,person:'משותף',event:''},{category:'משפחה',cents:4000,person:'אישי',event:'אירוע'}]);assert.deepEqual(next,expected);assert.deepEqual(next.details,p.details);assert.deepEqual(next.cardBilling,p.cardBilling);assert.deepEqual(next.reportInbox,p.reportInbox);assert.deepEqual(forecast(next),forecast(p));assert.equal(budgetDetailView(next,annotationOptions).valueCents,10001);assert.equal(analyticalExpenseDetails(next).length,2);assert.equal(annotationSource(next,c.detailId,annotationOptions).id,c.detailId);assert.deepEqual(p,before);const reset=prepareDetailAnnotation(next,c.detailId,{merchant:draft.merchant,parts:[]},annotationOptions);assert.deepEqual(reset,annotateExpenseDetail(next,c.detailId,[]));assert.deepEqual(reset.details,p.details)}finally{c.db.close()}})
